    <script>
    (()=>{const cart=new Map(),box=document.getElementById('cart'),hidden=document.getElementById('hidden-items'),subtotal=document.getElementById('subtotal');function render(){box.replaceChildren();hidden.replaceChildren();let total=0;if(!cart.size){const empty=document.createElement('p');empty.className='text-sm text-slate-500';empty.textContent='Add products to begin.';box.append(empty)}for(const [id,p] of cart){total+=p.price*p.qty;const row=document.createElement('div');row.className='flex items-center justify-between gap-2 border-b pb-2';const name=document.createElement('span');name.className='text-sm';name.textContent=p.name;const controls=document.createElement('div');controls.className='flex items-center gap-2';const minus=document.createElement('button');minus.type='button';minus.setAttribute('aria-label','Decrease quantity');minus.className='rounded border px-2';minus.textContent='−';const count=document.createElement('span');count.textContent=String(p.qty);const plus=document.createElement('button');plus.type='button';plus.setAttribute('aria-label','Increase quantity');plus.className='rounded border px-2';plus.textContent='+';minus.onclick=()=>{if(--p.qty<1)cart.delete(id);render()};plus.onclick=()=>{if(p.qty<p.stock)p.qty++;render()};controls.append(minus,count,plus);row.append(name,controls);box.append(row);const a=document.createElement('input'),b=document.createElement('input');a.type=b.type='hidden';a.name=`items[${id}][product_id]`;a.value=id;b.name=`items[${id}][quantity]`;b.value=String(p.qty);hidden.append(a,b)}subtotal.textContent=total.toLocaleString()}document.querySelectorAll('.add-to-cart').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.id,p=cart.get(id)||{name:button.dataset.name,price:Number(button.dataset.price),stock:Number(button.dataset.stock),qty:0};if(p.qty<p.stock)p.qty++;cart.set(id,p);render()}));document.getElementById('checkout-form').addEventListener('submit',e=>{if(!cart.size){e.preventDefault();alert('Add at least one product.')}})})();
    </script>
